<?php
declare(strict_types=1);namespace Acorn\SafetyHealthcheck\Admin;use Acorn\SafetyHealthcheck\Database\Schema;final class AssessmentsPage{public function render():void{if(!current_user_can('manage_acorn_healthcheck'))wp_die('Forbidden',403);global$wpdb;$rows=$wpdb->get_results('SELECT id,status,jurisdiction,sector,priority_count,review_count,completed_at FROM '.Schema::table('assessments').' ORDER BY id DESC LIMIT 100',ARRAY_A);echo'<div class="wrap"><h1>Assessments</h1><table class="widefat"><thead><tr><th>ID</th><th>Status</th><th>Jurisdiction</th><th>Findings</th></tr></thead><tbody>';foreach($rows as$r)echo'<tr><td>'.(int)$r['id'].'</td><td>'.esc_html($r['status']).'</td><td>'.esc_html($r['jurisdiction']).'</td><td>'.(int)$r['priority_count'].' priority, '.(int)$r['review_count'].' review</td></tr>';echo'</tbody></table></div>';}}
